using System;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>
    /// A four-sided piece cut from a surface. Corners are stored in order around the panel.
    /// </summary>
    public sealed class Panel
    {
        private readonly double[] _edges;
        private readonly double _area;
        private readonly Point3d _center;
        private readonly double _deviation;

        public Panel(Point3d[] corners, int index)
        {
            if (corners == null || corners.Length != 4)
                throw new ArgumentException("A panel needs exactly four corners.", nameof(corners));

            Corners = new[] { corners[0], corners[1], corners[2], corners[3] };
            Index = index;

            _edges = new[]
            {
                Corners[0].DistanceTo(Corners[1]),
                Corners[1].DistanceTo(Corners[2]),
                Corners[2].DistanceTo(Corners[3]),
                Corners[3].DistanceTo(Corners[0]),
            };
            _area = ComputeArea();
            _center = ComputeCenter();
            _deviation = ComputeDeviation();
        }

        /// <summary>Corner points in order around the panel (4 items).</summary>
        public Point3d[] Corners { get; }

        /// <summary>Position in the grid the panel was cut from (row-major, U varies fastest).</summary>
        public int Index { get; }

        /// <summary>Area of the quad, split into two triangles.</summary>
        public double Area => _area;

        /// <summary>Average of the four corners.</summary>
        public Point3d Center => _center;

        /// <summary>Distance from the fourth corner to the plane through the first three.</summary>
        public double Deviation => _deviation;

        /// <summary>Edge lengths 0-1, 1-2, 2-3, 3-0.</summary>
        public double[] EdgeLengths => (double[])_edges.Clone();

        /// <summary>Diagonal lengths 0-2 and 1-3.</summary>
        public double[] DiagonalLengths => new[]
        {
            Corners[0].DistanceTo(Corners[2]),
            Corners[1].DistanceTo(Corners[3]),
        };

        /// <summary>Rectangle width used for nesting: mean of the first and third edge.</summary>
        public double Width => (_edges[0] + _edges[2]) * 0.5;

        /// <summary>Rectangle height used for nesting: mean of the second and fourth edge.</summary>
        public double Height => (_edges[1] + _edges[3]) * 0.5;

        /// <summary>A new closed polyline curve along the panel outline.</summary>
        public PolylineCurve CreateOutline()
        {
            return new PolylineCurve(new[] { Corners[0], Corners[1], Corners[2], Corners[3], Corners[0] });
        }

        private double ComputeArea()
        {
            Vector3d diagonal = Corners[2] - Corners[0];
            Vector3d t1 = Vector3d.CrossProduct(Corners[1] - Corners[0], diagonal);
            Vector3d t2 = Vector3d.CrossProduct(diagonal, Corners[3] - Corners[0]);
            return 0.5 * (t1.Length + t2.Length);
        }

        private Point3d ComputeCenter()
        {
            double x = 0, y = 0, z = 0;
            foreach (Point3d p in Corners)
            {
                x += p.X;
                y += p.Y;
                z += p.Z;
            }
            return new Point3d(x / 4.0, y / 4.0, z / 4.0);
        }

        private double ComputeDeviation()
        {
            Vector3d normal = Vector3d.CrossProduct(Corners[1] - Corners[0], Corners[2] - Corners[0]);
            if (normal.Length < 1e-12)
                return double.PositiveInfinity; // first three corners are collinear: no plane to measure against

            normal.Unitize();
            Vector3d v = Corners[3] - Corners[0];
            return Math.Abs(normal.X * v.X + normal.Y * v.Y + normal.Z * v.Z);
        }
    }
}

