    {
        public PanelGoo() { }

        public PanelGoo(Panel panel) : base(panel) { }

        public PanelGoo(PanelGoo other) : base(other) { }

        public override bool IsValid => Value != null;

        public override string TypeName => "Panel";

        public override string TypeDescription => "A four-sided facade panel";

        public override IGH_Goo Duplicate() => new PanelGoo(this);

        public override string ToString() => Value == null ? "Empty panel" : $"Panel {Value.Index}";
    }
}

