using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    /// <summary>Shared helpers for reading and writing Panel values in components.</summary>
    internal static class PanelIO
    {
        /// <summary>Reads every panel on an input list, skipping empty items.</summary>
        public static List<Panel> GetPanels(IGH_DataAccess da, int index)
        {
            var goos = new List<PanelGoo>();
            var panels = new List<Panel>();
            if (!da.GetDataList(index, goos)) return panels;

            foreach (PanelGoo goo in goos)
            {
                if (goo != null && goo.Value != null) panels.Add(goo.Value);
            }
            return panels;
        }

        /// <summary>Wraps panels for output.</summary>
        public static List<PanelGoo> Wrap(IEnumerable<Panel> panels)
        {
            var goos = new List<PanelGoo>();
            foreach (Panel p in panels) goos.Add(new PanelGoo(p));
            return goos;
        }
    }
}

