using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

namespace BenchPlugin.Facade
{
    /// <summary>One panel placed on a sheet. X and Y are relative to the sheet's lower-left corner.</summary>
    public sealed class NestedPanel
    {
        public int PanelIndex;
        public int Sheet;
        public double X;
        public double Y;
        public double Width;
        public double Height;
        public bool Turned;
    }

    public sealed class NestResult
    {
        /// <summary>Placed panels, ordered by their position in the input list.</summary>
        public List<NestedPanel> Placed = new List<NestedPanel>();
        /// <summary>Input positions of panels that fit on no sheet.</summary>
        public List<int> Unplaced = new List<int>();
        public int SheetCount;
        /// <summary>Placed rectangle area divided by (SheetCount x sheet area).</summary>
        public double Utilization;
    }

    /// <summary>
    /// Shelf nesting of panel rectangles. Parts are placed tallest first, left to right on a shelf.
    /// A part is turned only when it fits turned and not upright. A new shelf is opened above when
    /// a part does not fit on the current one, and a new sheet when it does not fit on a fresh shelf.
    /// </summary>
    public static class ShelfNester
    {
        private sealed class Sheet
        {
            public int Index;
            public double ShelfY;
            public double ShelfHeight;
            public double CursorX;
            public bool ShelfEmpty = true;
        }

        public static NestResult Run(
            IList<Panel> panels,
            double sheetWidth,
            double sheetHeight,
            double spacing,
            CancellationToken token,
            Action<int> progress)
        {
            var result = new NestResult();
            int n = panels.Count;
            var widths = new double[n];
            var heights = new double[n];
            for (int i = 0; i < n; i++)
            {
                widths[i] = panels[i].Width;
                heights[i] = panels[i].Height;
            }

            // Tallest first, then widest.
            List<int> order = Enumerable.Range(0, n)
                .OrderByDescending(i => heights[i])
                .ThenByDescending(i => widths[i])
                .ToList();

            var sheets = new List<Sheet>();
            int lastPercent = -1;

            for (int k = 0; k < order.Count; k++)
            {
                token.ThrowIfCancellationRequested();

                int i = order[k];
                double w = widths[i];
                double h = heights[i];
                bool turned;
                double x, y;

                bool placed = false;
                x = y = 0;
                turned = false;

                Sheet current = sheets.Count > 0 ? sheets[sheets.Count - 1] : null;

                // 1. Current shelf: upright if it fits, otherwise turned if that fits.
                if (current != null)
                {
                    placed = TryPlaceOnShelf(current, sheetWidth, sheetHeight, spacing, w, h, out x, out y, out turned);
                }

                // 2. Open a new shelf above on the current sheet.
                if (!placed && current != null && !current.ShelfEmpty)
                {
                    StartNewShelf(current, spacing);
