using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    public class PlanarityComponent : GH_Component
    {
        public PlanarityComponent()
            : base("Planarity", "Planarity", "Measures how far each panel deviates from being flat", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("9c4b2e77-1f5a-4e3d-8b6c-4a2d9e1f0c33");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to check", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Largest deviation that still counts as flat", GH_ParamAccess.item, 0.5);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Deviation", "D", "Distance from corner 4 to the plane through corners 1-3", GH_ParamAccess.list);
            pManager.AddBooleanParameter("Flat", "F", "True when the deviation is at most the tolerance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Flat Count", "N", "Number of flat panels", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double tolerance = 0.5;
            if (!DA.GetData(1, ref tolerance)) return;

            var deviations = new List<double>(panels.Count);
            var flat = new List<bool>(panels.Count);
            int flatCount = 0;

            foreach (Panel panel in panels)
            {
                double d = panel.Deviation;
                bool isFlat = d <= tolerance;
                deviations.Add(d);
                flat.Add(isFlat);
                if (isFlat) flatCount++;
            }

            int notFlat = panels.Count - flatCount;
            if (notFlat * 2 > panels.Count)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{notFlat} of {panels.Count} panels are not flat (deviation above {tolerance}).");
            }

            DA.SetDataList(0, deviations);
            DA.SetDataList(1, flat);
            DA.SetData(2, flatCount);
        }
    }
}

