    public class PanelStatsComponent : GH_Component
    {
        public PanelStatsComponent()
            : base("Panel Stats", "Panel Stats", "Total, minimum, maximum and mean panel area", "Facade", "Analysis")
        {
        }

        public override Guid ComponentGuid => new Guid("c5a1f0e8-6b2d-4a7e-8f3c-6d4b1e9a2f55");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to summarise", GH_ParamAccess.list);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddNumberParameter("Total Area", "Tot", "Sum of panel areas", GH_ParamAccess.item);
            pManager.AddNumberParameter("Min Area", "Min", "Smallest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Max Area", "Max", "Largest panel area", GH_ParamAccess.item);
            pManager.AddNumberParameter("Mean Area", "Avg", "Average panel area", GH_ParamAccess.item);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            if (panels.Count == 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "No panels to measure.");
                return;
            }

            double total = 0, min = double.MaxValue, max = double.MinValue;
            foreach (Panel panel in panels)
            {
                double a = panel.Area;
                total += a;
                if (a < min) min = a;
                if (a > max) max = a;
            }

            DA.SetData(0, total);
            DA.SetData(1, min);
            DA.SetData(2, max);
            DA.SetData(3, total / panels.Count);
        }
    }
}

