using System;
using System.Collections.Generic;
using Grasshopper.Kernel;

namespace BenchPlugin.Facade
{
    public class GroupIdenticalPanelsComponent : GH_Component
    {
        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Groups panels whose edge and diagonal lengths match within tolerance", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("2d7b9e41-5c3f-4e8a-a0d6-7e5c2f1b9a66");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to group", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Largest allowed length difference", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel, from 0 in order of first appearance", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            pManager.AddParameter(new Param_Panel(), "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double tolerance = 1.0;
            if (!DA.GetData(1, ref tolerance)) return;

            var groups = new List<int>(panels.Count);
            var representatives = new List<Panel>();
            var representativeKeys = new List<double[]>();

            foreach (Panel panel in panels)
            {
                double[] key = Signature(panel);

                int group = -1;
                for (int g = 0; g < representativeKeys.Count; g++)
                {
                    if (Matches(representativeKeys[g], key, tolerance))
                    {
                        group = g;
                        break;
                    }
                }

                if (group < 0)
                {
                    group = representatives.Count;
                    representatives.Add(panel);
                    representativeKeys.Add(key);
                }
                groups.Add(group);
            }

            DA.SetDataList(0, groups);
            DA.SetData(1, representatives.Count);
            DA.SetDataList(2, PanelIO.Wrap(representatives));
        }

        /// <summary>Four sorted edge lengths followed by two sorted diagonal lengths.</summary>
        private static double[] Signature(Panel panel)
        {
            double[] edges = panel.EdgeLengths;
            double[] diagonals = panel.DiagonalLengths;
            Array.Sort(edges);
            Array.Sort(diagonals);

            var key = new double[6];
            edges.CopyTo(key, 0);
            diagonals.CopyTo(key, 4);
            return key;
        }

        private static bool Matches(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
            {
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            }
            return true;
        }
    }
}

