using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Grasshopper.Kernel;
using Rhino;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    public class NestOnSheetsComponent : GH_Component
    {
        /// <summary>Horizontal distance between neighbouring sheet origins, beyond the sheet width.</summary>
        private const double SheetGap = 100.0;

        private NestJob _job;

        public NestOnSheetsComponent()
            : base("Nest On Sheets", "Nest", "Nests panel rectangles on sheets with a shelf algorithm", "Facade", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("8f1c4a63-9e2b-4d7f-b5a8-8f6d3c0e1b77");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddParameter(new Param_Panel(), "Panels", "P", "Panels to nest", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "W", "Width of each sheet", GH_ParamAccess.item, 3000.0);
            pManager.AddNumberParameter("Sheet Height", "H", "Height of each sheet", GH_ParamAccess.item, 1500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 10.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Rectangle of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "N", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed area divided by total sheet area", GH_ParamAccess.item);
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            CancelJob();
            base.RemovedFromDocument(document);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = PanelIO.GetPanels(DA, 0);
            double sheetWidth = 3000.0, sheetHeight = 1500.0, spacing = 10.0;
            if (!DA.GetData(1, ref sheetWidth)) return;
            if (!DA.GetData(2, ref sheetHeight)) return;
            if (!DA.GetData(3, ref spacing)) return;

            if (sheetWidth <= 0 || sheetHeight <= 0 || spacing < 0)
            {
                CancelJob();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error,
                    "Sheet Width and Sheet Height must be positive, and Spacing cannot be negative.");
                return;
            }

            if (panels.Count == 0)
            {
                CancelJob();
                Message = string.Empty;
                return;
            }

            double[] key = BuildKey(panels, sheetWidth, sheetHeight, spacing);
            if (_job == null || !_job.Key.SequenceEqual(key))
            {
                // Inputs changed: stop the old run and start a new one.
                CancelJob();
                _job = new NestJob(key);
                StartJob(_job, panels, sheetWidth, sheetHeight, spacing);
                Message = "Nesting 0%";
                return;
            }

            if (_job.Error != null)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Nesting failed: " + _job.Error);
                Message = string.Empty;
                return;
            }

            if (!_job.IsDone)
            {
                Message = $"Nesting {_job.Progress}%";
                return;
            }

            NestResult result = _job.Result;
            double offsetStep = sheetWidth + SheetGap;

            var outlines = new List<Curve>(result.Placed.Count);
            var sheets = new List<int>(result.Placed.Count);
            foreach (NestedPanel p in result.Placed)
            {
                double x0 = p.Sheet * offsetStep + p.X;
                double y0 = p.Y;
                double x1 = x0 + p.Width;
                double y1 = y0 + p.Height;
                outlines.Add(new PolylineCurve(new[]
                {
                    new Point3d(x0, y0, 0),
                    new Point3d(x1, y0, 0),
                    new Point3d(x1, y1, 0),
                    new Point3d(x0, y1, 0),
                    new Point3d(x0, y0, 0),
                }));
                sheets.Add(p.Sheet);
            }

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, result.SheetCount);
            DA.SetData(3, result.Utilization);

            Message = $"{result.SheetCount} sheet(s)";

            if (result.Unplaced.Count > 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning,
                    $"{result.Unplaced.Count} of {panels.Count} panels fit on no sheet and were left out.");
            }
        }

        private void StartJob(NestJob job, List<Panel> panels, double sheetWidth, double sheetHeight, double spacing)
        {
            Task.Run(() =>
            {
                try
                {
                    job.Result = ShelfNester.Run(panels, sheetWidth, sheetHeight, spacing, job.Token, pct =>
                    {
                        job.Progress = pct;
                        RhinoApp.InvokeOnUiThread(new Action(() =>
                        {
                            if (!ReferenceEquals(_job, job)) return;
                            Message = $"Nesting {pct}%";
                            OnDisplayExpired(false);
                        }));
                    });
                    job.IsDone = true;
                }
                catch (OperationCanceledException)
                {
                    return; // a newer run replaced this one
                }
                catch (Exception ex)
                {
                    job.Error = ex.Message;
                }

                RhinoApp.InvokeOnUiThread(new Action(() =>
                {
                    if (ReferenceEquals(_job, job)) ExpireSolution(true);
                }));
            }, job.Token);
        }

        private void CancelJob()
        {
            if (_job == null) return;
            _job.Cancel();
            _job = null;
        }

        /// <summary>Inputs that decide the layout: sheet size, spacing and each panel's rectangle.</summary>
        private static double[] BuildKey(List<Panel> panels, double sheetWidth, double sheetHeight, double spacing)
        {
            var key = new double[3 + panels.Count * 2];
            key[0] = sheetWidth;
            key[1] = sheetHeight;
            key[2] = spacing;
            for (int i = 0; i < panels.Count; i++)
            {
                key[3 + 2 * i] = panels[i].Width;
                key[4 + 2 * i] = panels[i].Height;
            }
            return key;
        }

        private sealed class NestJob
        {
            private readonly CancellationTokenSource _cts = new CancellationTokenSource();

            public NestJob(double[] key)
            {
                Key = key;
            }

            public double[] Key { get; }
            public CancellationToken Token => _cts.Token;

            // Written on the worker thread, read on the UI thread.
            public volatile int Progress;
            public volatile bool IsDone;
            public volatile string Error;
            public NestResult Result;

            public void Cancel()
            {
                _cts.Cancel();
            }
        }
    }
}

