                }
                else
                {
                    try
                    {
                        File.WriteAllText(target, csv);
                        written = true;
                    }
                    catch (Exception ex)
                    {
                        AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Could not write the CSV: " + ex.Message);
                    }
                }
            }

            DA.SetData(0, csv);
            DA.SetData(1, written);
        }

        /// <summary>Columns: index, width, height, area, deviation. Width and height match Nest On Sheets.</summary>
        private static string BuildCsv(List<Panel> panels)
        {
            var sb = new StringBuilder();
            sb.Append("index,width,height,area,deviation");
            sb.Append('\n');
            foreach (Panel p in panels)
            {
                sb.Append(p.Index.ToString(CultureInfo.InvariantCulture));
                sb.Append(',');
                sb.Append(Format(p.Width));
                sb.Append(',');
                sb.Append(Format(p.Height));
                sb.Append(',');
                sb.Append(Format(p.Area));
                sb.Append(',');
                sb.Append(Format(p.Deviation));
                sb.Append('\n');
            }
            return sb.ToString();
        }

        private static string Format(double value)
        {
            return double.IsInfinity(value) || double.IsNaN(value)
                ? "NA"
                : value.ToString("0.###", CultureInfo.InvariantCulture);
        }
    }
}

